// Simplified from this app's scheduler
function nextInterval(card, grade) {
  if (grade === "again") return 1;
  const reps = card.reps + 1;
  if (reps === 1) return { hard: 1, good: 2, easy: 4 }[grade];
  if (reps === 2) return { hard: 3, good: 6, easy: 10 }[grade];
  return Math.round(card.interval * card.ease);
}
